    private java.lang.StringBuffer fieldBuffer = new java.lang.StringBuffer();

    // This should not match because it's a method parameter type. Method signature changes
    // are not safely handled by a simple DSL rule without broader architectural analysis.
    public void processBuffer(java.lang.StringBuffer paramBuffer) {
        paramBuffer.append("data");
    }

    // This should not match because it's a method return type.
    public java.lang.StringBuffer getBuffer() {
